bool _resumableTransportFailure(ErrorEvent event, CancelToken? cancelToken) {
  if (cancelToken != null &&
      cancelToken.isCancelled &&
      cancelToken.cancelReason is! RunIdleWatchdogFire) {
    return false;
  }
