          error,
          state,
          cancelToken,
          resume,
          delay,
          attempt,
          maxAttempts,
        )) {
          return;
        }
      case _AbortedPartial(:final snapshot, :final keptBlocks, :final reason):
        state.lastFailure = snapshot;
        state.attemptLog.add(_shortReason(snapshot.errorMessage));
