/// every net below it (issue #926 — a gateway-wrapped budget error quotes
/// "500 … please try again later"), auth failures stand, context overflow
/// belongs …

                  api: model.api,
                  provider: model.provider,
                  model: model.id,
                  usage: Usage.zero,
                  stopReason: StopReason.error,
                  errorMessage: '$error',
