  Duration delay,
  int attempt,
  int maxAttempts,
  String reason,
) async {
  final survived = await transientRetrySleeper(delay, cancelToken);
  transientRetryNotice?.call(
    attempt,
    maxAttempts,
    survived ? delay : Duration.zero,
    reason,
