({Map<String, dynamic> message, int lastIndex}) _convertToolResultGroup(
  List<Message> messages,
  int startIndex,
) {
  final toolResults = <Map<String, dynamic>>[];
  var j = startIndex;
  for (; j < messages.length && messages[j] is ToolResultMessage; j++) {
